static inline void fd_adx_cache_credit( fd_ed25519_cache_t * cache ) { cache->credit = fd_ulong_min( cache->credit+1UL, FD_ADX_CACHE_CREDIT_MAX ); }

fd_ed25519_cache_ent_t const *
fd_ed25519_cache_query( fd_ed25519_cache_t * cache,
                        uchar const public_key[ 32 ],
                        ulong * _h ) {
  ulong h = fd_hash( cache->seed, public_key, 32UL );
  ulong idx = h & (cache->set_cnt-1UL);
  *_h = h;
  fd_ed25519_cache_set_t * set = cache->set + idx;
  ulong tick = ++cache->tick;
  for( ulong w=0UL; w<FD_ADX_CACHE_WAY_CNT; w++ ) {
    if( FD_LIKELY( set->use[ w ] && fd_memeq( set->key[ w ], public_key, 32UL ) ) ) {
      set->use[ w ] = tick;
      cache->hit_cnt++;
      return (fd_ed25519_cache_ent_t const *)( cache->tbl + (FD_ADX_CACHE_WAY_CNT*idx+w)*FD_ADX_SPLIT_A_TBL_CNT );
    }
  }
  cache->miss_cnt++;
  return NULL;
}

/* the admission of public_key (hash h) with its decoded -A at hand: the filter note on the first
   offer, the table build on the second if credits allow, into the least recently used way; a
   key already in its set (inserted by an earlier miss of the same batch) is left as it is */
static void
fd_adx_cache_admit_point( fd_ed25519_cache_t * cache, uchar const public_key[ 32 ], ulong h, ulong * neg_a ) {
  ulong * slot = cache->filter + (fd_ulong_hash( h ) & (cache->filter_cnt-1UL));
  if( FD_LIKELY( *slot!=h ) ) { *slot = h; return; }
  ulong idx = h & (cache->set_cnt-1UL);
  fd_ed25519_cache_set_t * set = cache->set + idx;
  for( ulong w=0UL; w<FD_ADX_CACHE_WAY_CNT; w++ ) if( FD_UNLIKELY( set->use[ w ] && fd_memeq( set->key[ w ], public_key, 32UL ) ) ) { *slot = 0UL; return; }
  if( FD_UNLIKELY( cache->credit<FD_ADX_CACHE_BUILD_COST ) ) return;
  cache->credit -= FD_ADX_CACHE_BUILD_COST;
  *slot = 0UL;
  ulong w = 0UL;
  for( ulong v=1UL; v<FD_ADX_CACHE_WAY_CNT; v++ ) w = fd_ulong_if( set->use[ v ]<set->use[ w ], v, w );
  fd_adx_split_table_a( cache->tbl + (FD_ADX_CACHE_WAY_CNT*idx+w)*FD_ADX_SPLIT_A_TBL_CNT, neg_a );
  memcpy( set->key[ w ], public_key, 32UL );
  set->use[ w ] = ++cache->tick;
  cache->insert_cnt++;
}

void
fd_ed25519_cache_admit( fd_ed25519_cache_t * cache,
                        uchar const public_key[ 32 ],
                        ulong h ) {
  /* the first offer only notes the key; A is decoded for a build */
  ulong * slot = cache->filter + (fd_ulong_hash( h ) & (cache->filter_cnt-1UL));
  if( FD_LIKELY( *slot!=h ) ) { *slot = h; return; }
  ulong idx = h & (cache->set_cnt-1UL);
  fd_ed25519_cache_set_t * set = cache->set + idx;
  for( ulong w=0UL; w<FD_ADX_CACHE_WAY_CNT; w++ ) if( FD_UNLIKELY( set->use[ w ] && fd_memeq( set->key[ w ], public_key, 32UL ) ) ) { *slot = 0UL; return; }
  if( FD_UNLIKELY( cache->credit<FD_ADX_CACHE_BUILD_COST ) ) return;
  ulong A[16];
  if( FD_UNLIKELY( !fd_adx_point_decode1( A, public_key ) ) ) return;
  fd_adx_point_neg( A, A );
  fd_adx_cache_admit_point( cache, public_key, h, A );
}

/* one signature through the cache: the lookup, the checks and the equation with or without the
   table, a credit for the evaluated equation, the admission of a passing miss */
static int
fd_adx_verify_one( uchar const msg[], ulong msg_sz, uchar const sig[ 64 ], uchar const public_key[ 32 ],
                  fd_sha512_t * sha, fd_ed25519_cache_t * cache, int * _ok ) {
  if( FD_UNLIKELY( !fd_curve25519_scalar_validate( sig+32 ) ) ) return FD_ED25519_ERR_SIG;
  ulong h;
  fd_adx_tbl_t const * a_tbl = (fd_adx_tbl_t const *)fd_ed25519_cache_query( cache, public_key, &h );
  ulong negA[16];
  int want = *_ok;
  int err = fd_adx_verify_core( msg, msg_sz, sig, public_key, sha, a_tbl, _ok, negA );
  if( FD_UNLIKELY( err ) ) return err;
  if( FD_LIKELY( want ) ) {
    fd_adx_cache_credit( cache );
    if( FD_LIKELY( *_ok && !a_tbl ) ) fd_adx_cache_admit_point( cache, public_key, h, negA );
  }
  return FD_ED25519_SUCCESS;
}

int
fd_ed25519_verify_cached( uchar const msg[], /* msg_sz */
                          ulong msg_sz,
                          uchar const sig[ 64 ],
                          uchar const public_key[ 32 ],
                          fd_sha512_t * sha,
                          fd_ed25519_cache_t * cache ) {
  int ok = 1;
  int err = fd_adx_verify_one( msg, msg_sz, sig, public_key, sha, cache, &ok );
  if( FD_UNLIKELY( err ) ) return err;
  return FD_LIKELY( ok ) ? FD_ED25519_SUCCESS : FD_ED25519_ERR_MSG;
}

/* the pending misses of a cached batch, verified together: a lane group when enough, else one by
   one; each evaluated equation earns a credit and each passing item is offered for admission */
static void
fd_adx_verify_misses( fd_ed25519_cache_t * cache, uchar const * const msgs[], ulong const msg_szs[], uchar const * const sigs[],
                     uchar const * const public_keys[], fd_sha512_t * shas[], ulong const hs[], int * const results[], ulong n ) {
  for( ulong i=0; i<n; i++ ) {
    ulong negA[16];
    int ok = 1;
    int err = fd_adx_verify_core( msgs[i], msg_szs[i], sigs[i], public_keys[i], shas[i], NULL, &ok, negA );
    if( FD_UNLIKELY( err ) ) { *results[i] = err; continue; }
    fd_adx_cache_credit( cache );
    *results[i] = ok ? FD_ED25519_SUCCESS : FD_ED25519_ERR_MSG;
    if( FD_LIKELY( ok ) ) fd_adx_cache_admit_point( cache, public_keys[i], hs[i], negA );
  }
}

void
fd_ed25519_verify_batch_multi_msg_cached( uchar const * const msgs[],
                                          ulong const msg_szs[],
                                          uchar const * const sigs[],
                                          uchar const * const public_keys[],
                                          fd_sha512_t * shas[],
                                          int results[],
                                          ulong batch_sz,
                                          fd_ed25519_cache_t * cache ) {
  /* lookup first: hits are verified at once with their table, misses pend for a group */
  uchar const * pm[8], * ps[8], * pk[8]; ulong psz[8], ph[8]; fd_sha512_t * psha[8]; int * pr[8]; ulong n = 0UL;
  for( ulong j=0; j<batch_sz; j++ ) {
    if( FD_UNLIKELY( !fd_curve25519_scalar_validate( sigs[j]+32 ) ) ) { results[j] = FD_ED25519_ERR_SIG; continue; }
    ulong h;
    fd_adx_tbl_t const * a_tbl = (fd_adx_tbl_t const *)fd_ed25519_cache_query( cache, public_keys[j], &h );
    if( FD_LIKELY( a_tbl ) ) {
      int ok = 1;
      int err = fd_adx_verify_core( msgs[j], msg_szs[j], sigs[j], public_keys[j], shas[j], a_tbl, &ok, NULL );
      if( FD_LIKELY( !err ) ) fd_adx_cache_credit( cache );
      results[j] = err ? err : ok ? FD_ED25519_SUCCESS : FD_ED25519_ERR_MSG;
      continue;
    }
    pm[n] = msgs[j]; psz[n] = msg_szs[j]; ps[n] = sigs[j]; pk[n] = public_keys[j]; psha[n] = shas[j]; ph[n] = h; pr[n] = results+j; n++;
    if( n==8UL ) { fd_adx_verify_misses( cache, pm, psz, ps, pk, psha, ph, pr, n ); n = 0UL; }
  }
  if( n ) fd_adx_verify_misses( cache, pm, psz, ps, pk, psha, ph, pr, n );
}

int
fd_ed25519_verify_batch_single_msg_cached( uchar const msg[], /* msg_sz */
                                           ulong const msg_sz,
                                           uchar const signatures[ 64 ], /* 64 * batch_sz */
                                           uchar const pubkeys[ 32 ], /* 32 * batch_sz */
                                           fd_sha512_t * shas[ 1 ], /* batch_sz */
                                           uchar const batch_sz,
                                           fd_ed25519_cache_t * cache ) {
  if( FD_UNLIKELY( batch_sz == 0 || batch_sz > 16 ) ) return FD_ED25519_ERR_SIG;
  uchar const * msgs[16], * sigs[16], * pks[16]; ulong szs[16]; int codes[16];
  for( ulong j=0; j<batch_sz; j++ ) { msgs[j] = msg; szs[j] = msg_sz; sigs[j] = signatures+64UL*j; pks[j] = pubkeys+32UL*j; }
  fd_ed25519_verify_batch_multi_msg_cached( msgs, szs, sigs, pks, shas, codes, batch_sz, cache );
  return fd_adx_verdict( codes, batch_sz );
}
